# Auto-generated by refactor: extracted verbatim from starter.py (factory + blueprints split).
import hashlib
import json
import logging
import os
import threading


_log = logging.getLogger(__name__)


# Onbellekler ThreadPoolExecutor worker'larindan (es zamanli FatSecret/LLM
# aramalari) yazilir; tek bir kilit, eviction sirasindaki `next(iter(cache))`
# + `del` bilesik isleminin baska bir thread'in mutasyonuyla cakisip
# "dictionary changed size during iteration" RuntimeError'i atmasini onler.
_cache_lock = threading.Lock()


# Makro onbellegi BAZ (basis) bazinda ayri tutulur: koc aramasi 100g-bazli,
# menu/social hatti PORSIYON-bazli deger yazar. Eski tek-sozluk tasarimda ayni
# ad altinda iki baz karisiyordu ('Pizza' 100g=267 kcal ← koc; menu bunu 1 tam
# porsiyon sanip 4-5 kat eksik gosteriyordu — ya da tersi, sisirme).
_macro_cache = {
    "per_100g": {},
    "per_serving": {},
}


_food_id_cache = {}   # name → fatsecret food_id


_MACRO_CACHE_MAX = 500


_FOOD_ID_CACHE_MAX = 1000


# İkinci katman (L2): Redis. Süreç-içi sözlük tek gunicorn worker'a ve süreç
# ömrüne hapsolur — her deploy/restart tüm makro birikimini sıfırlıyor, ileride
# worker sayısı artarsa her worker ayrı ısınıyordu. Redis varsa (prod) çözülen
# makrolar oraya da yazılır ve L1 miss'lerinde okunur; Redis yoksa (lokal/test)
# davranış birebir eski süreç-içi önbellektir. Tüm Redis hataları yutulur —
# önbellek arızası besin çözümlemesini asla düşürmez.
_MACRO_REDIS_PREFIX = "food:macros:v1:"
_MACRO_REDIS_TTL = int(os.getenv("FOODCACHE_REDIS_TTL", str(3 * 24 * 3600)))


def _get_redis():
    """app.extensions.redis_client'ı tembel (lazy) çöz — import döngüsünden ve
    test sırasında modül-yükleme yan etkisinden kaçınmak için çağrı anında."""
    try:
        from app.extensions import redis_client
        return redis_client
    except Exception:
        return None


def _macro_redis_key(basis, name):
    digest = hashlib.sha256(name.encode("utf-8")).hexdigest()
    return f"{_MACRO_REDIS_PREFIX}{basis}:{digest}"


def _l1_store(cache, name, macros):
    """FIFO tavanlı L1 yazımı — _cache_lock ALTINDA çağrılmalı."""
    if len(cache) >= _MACRO_CACHE_MAX and name not in cache:
        oldest = next(iter(cache))
        del cache[oldest]
    cache[name] = dict(macros)


def _get_cached_macros(item_names, basis="per_serving"):
    # setdefault: dis sozluk temizlense bile (test fixture'lari .clear() yapar)
    # namespace kendini onarir.
    # Okuma da _cache_lock altinda: es zamanli eviction (next(iter)+del) ile
    # cakismasin. Donen sozlukler KOPYA — tuketici mutasyonu onbellegi bozmasin (#12).
    hits = {}
    misses = []
    with _cache_lock:
        cache = _macro_cache.setdefault(basis, {})
        for name in item_names:
            cached = cache.get(name)
            if cached is not None:
                hits[name] = dict(cached)
            else:
                misses.append(name)

    # L1 miss'leri tek toplu MGET ile Redis'ten dene; bulunanlar L1'e geri konur
    # (ayni istek icindeki sonraki okumalar ve sonraki istekler sicak kalsin).
    if misses:
        r = _get_redis()
        if r is not None:
            try:
                keys = [_macro_redis_key(basis, n) for n in misses]
                raw_vals = r.mget(keys)
            except Exception as e:
                _log.warning("[FOODCACHE] Redis mget failed: %s: %s", type(e).__name__, e)
                raw_vals = None
            if raw_vals:
                still_missing = []
                redis_hits = {}
                for name, raw in zip(misses, raw_vals):
                    macros = None
                    if raw:
                        try:
                            parsed = json.loads(raw)
                            if isinstance(parsed, dict) and parsed.get("calories", 0) > 0:
                                macros = {
                                    "calories": float(parsed.get("calories", 0)),
                                    "protein": float(parsed.get("protein", 0)),
                                    "carbs": float(parsed.get("carbs", 0)),
                                    "fat": float(parsed.get("fat", 0)),
                                }
                        except (json.JSONDecodeError, TypeError, ValueError):
                            macros = None
                    if macros is not None:
                        redis_hits[name] = macros
                    else:
                        still_missing.append(name)
                if redis_hits:
                    with _cache_lock:
                        cache = _macro_cache.setdefault(basis, {})
                        for name, macros in redis_hits.items():
                            _l1_store(cache, name, macros)
                    hits.update({n: dict(m) for n, m in redis_hits.items()})
                    misses = still_missing
    return hits, misses


def _cache_macros(macro_map, basis="per_serving"):
    positive = {n: m for n, m in macro_map.items() if m.get("calories", 0) > 0}
    with _cache_lock:
        cache = _macro_cache.setdefault(basis, {})
        for name, macros in positive.items():
            # KOPYA sakla — uretici map'i sonradan mutasyon ederse onbellek
            # etkilenmesin (referansla paylasim aliasing'i, #12).
            _l1_store(cache, name, macros)

    if positive:
        r = _get_redis()
        if r is not None:
            try:
                pipe = r.pipeline(transaction=False)
                for name, macros in positive.items():
                    pipe.setex(_macro_redis_key(basis, name), _MACRO_REDIS_TTL,
                               json.dumps(macros, ensure_ascii=False))
                pipe.execute()
            except Exception as e:
                _log.warning("[FOODCACHE] Redis write failed: %s: %s", type(e).__name__, e)


def _get_cached_food_id(name, default=""):
    """name → food_id okumasını kilit altında yap. Düz `_food_id_cache.get(...)`
    okuması _cache_food_id'deki eviction `del`'iyle yarışıyordu; dict.get tek
    başına bozulmasa da dokümante kilit disiplinine uymak için tutarlı tut (3.6)."""
    if not name:
        return default
    with _cache_lock:
        return _food_id_cache.get(name.lower(), default)


def _cache_food_id(name, fid):
    """name → FatSecret food_id eşlemesini sınırlı (bounded) bir sözlükte tut.

    _macro_cache gibi FIFO tavanı uygula: kimliği doğrulanmış kullanıcılar
    serbest metin sorgularıyla bu önbelleği büyütebildiği için tavansız bırakmak
    yavaş bir bellek-büyümesi (DoS) vektörü olurdu."""
    if not name or not fid:
        return
    key = name.lower()
    with _cache_lock:
        if key not in _food_id_cache and len(_food_id_cache) >= _FOOD_ID_CACHE_MAX:
            oldest = next(iter(_food_id_cache))
            del _food_id_cache[oldest]
        _food_id_cache[key] = fid
